<?phpsession_start();// Database connection$host = 'localhost';$dbname = 'moviedb';$username = 'root';$password = '';$port = 3307;$conn = new mysqli($host, $username, $password, $dbname, $port);if ($conn->connect_error) {    die("Connection failed: " . $conn->connect_error);}if (!isset($_POST['security_answer']) || !isset($_SESSION['pending_username'])) {    die("Invalid access.");}$username = $_SESSION['pending_username'];$providedAnswer = trim($_POST['security_answer']);// Get stored hash from DB (in case not already in session)$sql = "SELECT security_answer_hash FROM users WHERE username = ?";$stmt = $conn->prepare($sql);$stmt->bind_param("s", $username);$stmt->execute();$result = $stmt->get_result();if ($result && $result->num_rows === 1) {    $row = $result->fetch_assoc();    $storedHash = $row['security_answer_hash'];    if (password_verify($providedAnswer, $storedHash)) {        // ✅ Correct answer        // Now log in the user fully        $_SESSION['username'] = $username;        unset($_SESSION['pending_username']); // clean up        // Determine where they came from        if (isset($_SESSION['login_origin']) && $_SESSION['login_origin'] === 'login') {            unset($_SESSION['login_origin']);            header("Location: security_question.php");  // normal login → homepage            exit;        } else {            // assumed from forgot password            header("Location: update_profile.php");            exit;        }    } else {        echo "Incorrect answer. Please go back and try again.";    }} else {    echo "User not found.";}$conn->close();?><!DOCTYPE html><html lang="en"><head>  <meta charset="UTF-8">  <title>Security Answer Verification</title>  <link rel="stylesheet" href="css/login.css"></head><body class="dark-theme">  <div class="login-container">    <div class="login-box">      <h2>Security Question Verification</h2>      <?php if (isset($error)): ?>        <div class="error"><?php echo htmlspecialchars($error); ?></div>        <a href="forgot_password.php" class="back-button">Try Again</a>      <?php endif; ?>    </div>  </div></body></html>